import{_ as r,c as a,o,ah as l}from"./chunks/framework.Ch_PcVtW.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART0/目次/0_context_summary.md","filePath":"scripts/output/PART0/目次/0_context_summary.md"}'),e={name:"scripts/output/PART0/目次/0_context_summary.md"};function i(s,t,n,_,c,u){return o(),a("div",null,[...t[0]||(t[0]=[l('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇以SKY-HI（日高光启）及其创立的BMSG为核心，记录公司成立第五年至2024年的发展轨迹。内容涵盖BE:FIRST、MAZZEL、Novel Core等艺人的成长，BMSG POSSE、BMSG FES及音乐节目、海外演出等项目，也涉及选秀、艺人培养、公司制度建设和音乐产业改革。日高光启从CEO、制作人及音乐人的多重视角出发，讨论“让社会变得更好”的管理理念、艺术表达、粉丝关系，以及日本娱乐产业持续发展的可能性。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>人物身份统一</strong>：SKY-HI为日高光启的艺名；需区分其本人、CEO、制作人、rapper等不同身份。</li><li><strong>团体与企划名称</strong>：BE:FIRST、MAZZEL、Novel Core、BMSG POSSE、BMSG FES、B-Town、D.U.N.K.、ATEEZ等应保留官方英文或官方中文译名。</li><li><strong>日本文化术语</strong>：“红白歌合战”“武道馆”“东京巨蛋”“夏季音乐节”等需准确传达其行业地位。</li><li><strong>行业概念</strong>：オーディション、音楽番組、エンタテイン、音楽的発露、自己肯定感、自尊心等不可机械直译，应结合语境处理。</li><li><strong>管理与艺术语气并存</strong>：涉及公司战略、制度和产业提言时保持理性严谨；谈及成员、音乐及梦想时保留热情、共情和想象力。</li><li><strong>第一人称与客观叙述</strong>：日高的发言应保留个人口吻；第三人称介绍则避免译成过度主观或宣传化文字。</li><li><strong>标题中的引号和问句</strong>：如“迷路”“喜欢就是喜欢”“大梦想”等具有概念性，需保持其隐喻和传播感。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>优先确认艺人、歌曲、节目、演出及企划的官方译法，首次出现时可保留英文并附常用中文说明。</li><li>根据语境区分“公司经营”“艺人制作”“音乐创作”“行业观察”四类表达，避免全部译成商业管理术语。</li><li>保留日高光启语言中的直接感、平等感和行动力，不宜过度书面化或拔高。</li><li>对“社会を善くする”“好き=好き”“自分自身を再定義”等核心表达，建议统一译法，形成全书概念线索。</li><li>处理日语省略、长句和标题时，可适度拆分，但不要削弱原文的逻辑递进与情绪力度。</li><li>对“マイルストーン”“フェーズ”“リリース”“コラボレーション”等行业外来语，可根据上下文译为“里程碑”“阶段”“发布/发行”“合作”，必要时保留英文注释。</li><li>涉及公司未来规划和产业提言时，避免将个人观点译成确定性结论；注意保留“思考、判断、意图、愿景”等语气层次。</li></ul>',6)])])}const m=r(e,[["render",i]]);export{d as __pageData,m as default};
